package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Shared email handling: a syntactic validity check and canonicalization to lower case, so
 * equivalent addresses written with different letter cases are stored and returned in one
 * uniform form. Used to normalize an owner request's optional email before it is persisted.
 */
final class Emails {

    private static final Pattern VALID = Pattern.compile(
            "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
                    + "@[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?"
                    + "(?:\\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)+$");

    private Emails() {
    }

    /** Whether {@code email} is a syntactically valid address. */
    static boolean isValid(String email) {
        return email != null && VALID.matcher(email).matches();
    }

    /** Returns {@code email} lower-cased: its canonical stored form. */
    static String normalize(String email) {
        return email.toLowerCase(Locale.ROOT);
    }
}
===== EnsureUniqueHousehold.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request that would place a new owner in a household already occupied by
 * an existing owner — one sharing the same last name and address, compared case-insensitively
 * with collapsed whitespace (see {@link Households#normalize(String)}). A request may opt in
 * to a shared household by setting {@code sharesHousehold} true, in which case the check is
 * skipped.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        for (Owner owner : ownerRepository.findAll()) {
            if (Households.matches(owner, request.getLastName(), request.getAddress())) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}
===== EnsureUniqueTelephone.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request whose E.164 telephone is already used by an existing owner. Runs
 * after {@link NormalizeOwnerTelephone} has canonicalized the body's telephone, comparing it
 * against every stored owner's E.164 number so numbers that differ only in separators or an
 * assumed country code are still treated as duplicates.
 */
public class EnsureUniqueTelephone {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = request.getTelephone();
        for (Owner owner : ownerRepository.findAll()) {
            if (Telephones.toE164(owner.getTelephone()).filter(telephone::equals).isPresent()) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}
