7	
8	/**
9	 * Rejects a create request that would place a new owner in a household already occupied by
10	 * an existing owner — one sharing the same last name and address, compared case-insensitively
11	 * with collapsed whitespace (see {@link Households#normalize(String)}). A request may opt in
12	 * to a shared household by setting {@code sharesHousehold} true, in which case the check is
13	 * skipped.
14	 */
15	public class EnsureUniqueHousehold {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
20	            return;
21	        }
22	        for (Owner owner : ownerRepository.findAll()) {
23	            if (Households.matches(owner, request.getLastName(), request.getAddress())) {
24	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
25	            }
26	        }
27	    }
28	}
