1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Shared household matching: canonicalizes the free-text fields that identify a household
12	 * (last name and address) so values that differ only in letter case or in the amount of
13	 * surrounding/internal whitespace compare equal. Used to detect when a new owner shares a
14	 * household with an existing one, and to derive the stable identifier that owners in the
15	 * same household share.
16	 */
17	final class Households {
18	
19	    private Households() {
20	    }
21	
22	    /**
23	     * Canonicalizes {@code value} for case-insensitive, whitespace-insensitive comparison:
24	     * trims the ends, collapses every run of whitespace to a single space and lower-cases
25	     * the result. Returns an empty string when {@code value} is {@code null}.
26	     */
27	    static String normalize(String value) {
28	        if (value == null) {
29	            return "";
30	        }
31	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
32	    }
33	
34	    /**
35	     * Whether {@code owner} belongs to the household identified by {@code lastName} and
36	     * {@code address}, comparing both fields canonically (see {@link #normalize(String)}).
37	     */
38	    static boolean matches(Owner owner, String lastName, String address) {
39	        return normalize(lastName).equals(normalize(owner.getLastName()))
40	                && normalize(address).equals(normalize(owner.getAddress()));
41	    }
42	
43	    /**
44	     * The stable identifier shared by every owner in the household identified by
45	     * {@code lastName} and {@code address}. Derived purely from the canonical household key,
46	     * so the same household always yields the same id without any coordination.
47	     */
48	    static String id(String lastName, String address) {
49	        String key = normalize(lastName) + "\n" + normalize(address);
50	        return "H-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
51	    }
52	
53	    private static String sha256Hex(String value) {
54	        try {
55	            byte[] digest = MessageDigest.getInstance("SHA-256")
56	                    .digest(value.getBytes(StandardCharsets.UTF_8));
57	            StringBuilder hex = new StringBuilder(digest.length * 2);
58	            for (byte b : digest) {
59	                hex.append(String.format("%02x", b));
60	            }
61	            return hex.toString();
62	        }
63	        catch (NoSuchAlgorithmException e) {
64	            throw new IllegalStateException("SHA-256 not available", e);
65	        }
66	    }
67	}
