6	/**
7	 * Normalizes a request's optional email: an absent (or blank) value is left untouched,
8	 * while a present value must be a syntactically valid address and is stored back lower-cased
9	 * so later steps persist and return the canonical form. Runs after the body has been
10	 * published; mutates that same instance in place. A present-but-invalid address is rejected
11	 * via {@link InvalidEmailException}.
12	 */
13	public class NormalizeOwnerEmail {
14	
15	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
16	        String email = request.getEmail();
17	        if (email == null || email.isBlank()) {
18	            return;
19	        }
20	        if (!Emails.isValid(email)) {
21	            throw new InvalidEmailException(email);
22	        }
23	        request.setEmail(Emails.normalize(email));
24	    }
25	}
